import java.util.*;

class Solution {
    public String minWindow(String s, String t) {
        if (s.length() < t.length()) {
            return "";
        }

        Map<Character, Integer> need = new HashMap<>();
        for (char ch : t.toCharArray()) {
            need.put(ch, need.getOrDefault(ch, 0) + 1);
        }

        List<int[]> filtered = new ArrayList<>();
        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);
            if (need.containsKey(ch)) {
                filtered.add(new int[] {i, ch});
            }
        }

        Map<Character, Integer> window = new HashMap<>();
        int required = need.size();
        int formed = 0;
        int bestLength = Integer.MAX_VALUE;
        int bestStart = 0;
        int left = 0;

        for (int right = 0; right < filtered.size(); right++) {
            char ch = (char) filtered.get(right)[1];
            window.put(ch, window.getOrDefault(ch, 0) + 1);
            if (window.get(ch).intValue() == need.get(ch).intValue()) {
                formed++;
            }

            while (formed == required) {
                int start = filtered.get(left)[0];
                int end = filtered.get(right)[0];
                if (end - start + 1 < bestLength) {
                    bestLength = end - start + 1;
                    bestStart = start;
                }

                char out = (char) filtered.get(left)[1];
                window.put(out, window.get(out) - 1);
                if (window.get(out) < need.get(out)) {
                    formed--;
                }
                left++;
            }
        }

        return bestLength == Integer.MAX_VALUE ? "" : s.substring(bestStart, bestStart + bestLength);
    }
}

class Solution {
    public String minWindow(String s, String t) {
        if (s.length() < t.length()) {
            return "";
        }

        int low = t.length();
        int high = s.length();
        int bestLength = -1;

        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (findWindowOfLength(s, t, mid) != -1) {
                bestLength = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }

        if (bestLength == -1) {
            return "";
        }
        int start = findWindowOfLength(s, t, bestLength);
        return s.substring(start, start + bestLength);
    }

    private int findWindowOfLength(String s, String t, int length) {
        int[] need = new int[128];
        for (char ch : t.toCharArray()) {
            need[ch]++;
        }

        int missing = t.length();
        for (int right = 0; right < s.length(); right++) {
            char in = s.charAt(right);
            if (need[in] > 0) {
                missing--;
            }
            need[in]--;

            if (right >= length) {
                char out = s.charAt(right - length);
                need[out]++;
                if (need[out] > 0) {
                    missing++;
                }
            }

            if (right >= length - 1 && missing == 0) {
                return right - length + 1;
            }
        }
        return -1;
    }
}
